_BLEND_INDEX = {name: i for i, name in enumerate(BLENDSHAPE_NAMES)}

coach._games()                                     # read games.json now, not later on the pipeline thread


def hold_back_crosstalk(act: dict[str, float], competitors: dict[str, tuple[float, frozenset[str]]]) -> dict[str, float]:
    """Hold a mapped gesture at 0 while another mapped gesture that shares none of its blendshapes is stronger than
    it by CROSSTALK_RATIO, both measured as level / on. A smile also lifts jawOpen, a wide-open mouth lifts the
    brows: the move the player meant is the one furthest past its own threshold, and the side effect lags well
    behind it. Two moves made on purpose together are both near full and both pass.
    competitors: gesture name -> (its on threshold, its blendshape sources; empty for learned moves)."""
    ratio = {name: act.get(name, 0.0) / on for name, (on, _) in competitors.items()}
    out = act
    for name, r in ratio.items():
        if r <= 0.0:
            continue
        sources = competitors[name][1]
        if any(other != name and r < config.CROSSTALK_RATIO * r_other and not (sources & competitors[other][1])
               for other, r_other in ratio.items()):
            if out is act:
                out = dict(act)
            out[name] = 0.0
    return out


def _load_model(player: str) -> GestureModel | None:
    path = profiles.gesture_model_path(player)
    return GestureModel.load(path) if os.path.exists(path) else None


class SessionStats:
    """Per mapped gesture: fires, near-misses and the peak level of each attempt, for the coach and the dashboard.

    An attempt opens when the level reaches NEAR_MISS_RATIO of `on` and closes when it falls below half of `on`.
    A closed attempt that did not fire is a near-miss. Updated on the pipeline thread; read with summary().
    """

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._g: dict[str, dict] = {}
        self._active_s = 0.0
        self._last_t: float | None = None

    def update(self, act: dict[str, float], thresholds: dict[str, dict[str, float]], tracked: set[str],
               fired: tuple[str, ...], t_s: float, active: bool) -> None:
        dt = 0.0 if self._last_t is None else min(max(t_s - self._last_t, 0.0), 0.1)
        self._last_t = t_s
        if not active:                             # calibrating, recording, paused or face lost
            return
        with self._lock:
            self._active_s += dt
            for name in tracked:
                th = thresholds.get(name)
                if th is None:
                    continue
                level = act.get(name, 0.0)
                g = self._g.setdefault(name, {"fires": 0, "near_misses": 0, "peaks": deque(maxlen=50),
                                              "open": False, "peak": 0.0, "fired": False})
                g["on"], g["off"] = th["on"], th["off"]
                did_fire = name in fired
                if did_fire:
                    g["fires"] += 1
                if not g["open"]:
                    if level >= config.NEAR_MISS_RATIO * th["on"] or did_fire:
                        g["open"], g["peak"], g["fired"] = True, level, did_fire
                    continue
                g["peak"] = max(g["peak"], level)
                g["fired"] = g["fired"] or did_fire
                if level < 0.5 * th["on"]:
                    g["peaks"].append(round(g["peak"], 3))
                    if not g["fired"]:
                        g["near_misses"] += 1
                    g["open"] = False

    def summary(self) -> dict:
        with self._lock:
            minutes = self._active_s / 60.0
            return {
                "active_s": round(self._active_s, 1),
                "gestures": {name: {"fires": g["fires"], "near_misses": g["near_misses"],
                                    "fires_per_min": round(g["fires"] / minutes, 2) if minutes > 0 else 0.0,
                                    "peaks": list(g["peaks"]), "on": g.get("on"), "off": g.get("off")}
                             for name, g in self._g.items()},
            }


class Runtime:
    def __init__(self, args):
        self.args = args
        self.player: str = args.player
        self.game: str = args.game

        # Source: mock, replay, or camera + tracker.
        if args.mock:
            self._source = MockSource()
        elif args.replay:
            self._source = ReplaySource(args.replay)
        else:
            self._source = None
        self._camera = None if self._source else Camera(index=args.camera)
        self._tracker = None if self._source else FaceTracker()
        self._recorder = Recorder(args.record) if args.record else None
        self._last_seq = -1
        self._draw_preview = self._source is not None and not args.no_server   # cartoon frame for the dashboard

        # Stages, in pipeline order.
        self._pad = make_gamepad(args.output)
        self._sip = SipPuff(None if args.serial == "off" else args.serial)
        self._calib = profiles.load_calibration(self.player)
        self._apply_breath_range(self.player)
        self._mapping = profiles.load_mapping(self.player, self.game)
        self._model = _load_model(self.player)
        self._normalizer = Normalizer(self._calib)
        self._fatigue = FatigueTracker()
        self._mapper = Mapper(self._mapping)
        self._gestures: GestureEngine
        self._thresholds: dict[str, dict[str, float]] = {}
        self._competitors: dict[str, tuple[float, frozenset[str]]] = {}
        self._rebuild_gestures()

        # Pipeline-thread state.
        self._calibrator: Calibrator | None = None
        self._breath_cal: BreathCalibrator | None = None
        self._take_recorder: TakeRecorder | None = None
        self._last_idle = True
        self._last_face_ns = 0
        self._frames = 0
        self._seen_errors: set[str] = set()
        self._capture_times: deque[int] = deque(maxlen=config.STATS_WINDOW)
        self._vision_ms: deque[float] = deque(maxlen=config.STATS_WINDOW)
        self._control_ms: deque[float] = deque(maxlen=config.STATS_WINDOW)
        self._total_ms: deque[float] = deque(maxlen=config.STATS_WINDOW)
        self._stats = SessionStats()               # per gesture, for the coach review
        self._fired_until: dict[str, int] = {}     # gesture or breath event -> perf_counter_ns it leaves "fired"

        # Shared with other threads: latest-value slots, plus commands and events that must not be dropped.
        self._lock = threading.Lock()
        self._requests: list[tuple[str, tuple]] = []
        self._events: list[dict] = []
        self._preview: tuple[np.ndarray, np.ndarray | None] | None = None
        self._dev_enabled = getattr(args, 'dev', False)
        self._dev_session = None
        self._dev_sessions = []
        self._dev_fit_threads = []
        self._dev_end_after_frame = False
        self._video_frame = None
        self._snapshot = self._build_snapshot(None, None, {}, ControlState(), None)

        self._stop = threading.Event()
        self._finished = threading.Event()         # set when a replay reaches its end
        self._thread: threading.Thread | None = None

    # ------------------------------------------------------------------ lifecycle

    def start(self) -> None:
        if self._camera:
            self._camera.start()
        self._sip.start()
        self._thread = threading.Thread(target=self._loop, name="pipeline", daemon=True)
        self._thread.start()
        threading.Thread(target=self._watch_profiles, name="profile-watch", daemon=True).start()

    def stop(self) -> None:
        self._stop.set()
        if self._thread:
            self._thread.join(timeout=2.0)
        closers = [lambda: self._pad.apply(ControlState(t_output_ns=time.perf_counter_ns())), self._pad.close,
                   self._sip.stop]
        if self._camera:
            closers.append(self._camera.stop)
        if self._tracker:
            closers.append(self._tracker.close)
        if self._recorder:
            closers.append(self._recorder.close)
        for close in closers:
            try:
                close()
            except Exception:
                log.exception("error while stopping")
        if self._dev_session:
            self._dev_session.finish('shutdown')
            self._dev_session = None
        for worker in self._dev_fit_threads:
            worker.join()
        for recording in self._dev_sessions:
            recording.wait()
        snap = self._snapshot
        log.info("stopped after %d frames, %.1f fps, median total latency %.2f ms",
                 self._frames, snap["fps"], snap["latency_ms"]["total"])

    @property
    def finished(self) -> bool:
        return self._finished.is_set()

    # ------------------------------------------------------------------ called by server.py (asyncio thread)

    def start_calibration(self, mode: str) -> None:
        if mode not in ("full", "quick", "breath"):
            self._event("error",
                        {"message": f"calibration mode must be full, quick or breath, not {mode!r}"})
            return
        if mode == "breath" and not self._sip.connected:
            self._event("error", {"message": "No breath sensor is connected"})
            return
        self._request("calibrate", mode)

    def record_gesture(self, name: str) -> None:
        self._request("record", name)

    def record_negative(self) -> None:
        self._request("record", None)

    def delete_gesture(self, name: str) -> None:
        self._request("delete_gesture", name)

    def set_mapping(self, mapping: dict) -> list[str]:
        """Returns validation errors, empty if applied. A mapping set by hand may use any expression, including
        ones calibration found weak: the player chose it (the coach still sticks to reliable ones)."""
        calib = dataclasses.replace(self._calib, reliable=list(BLENDSHAPE_NAMES)) if self._calib else None
        errors = profiles.validate_mapping(mapping, calib, self._learned(), self._sip.connected)
        if not errors:                             # what the Mapper itself refuses, e.g. off above on in a hand edit
            try:
                Mapper(mapping)
            except (ValueError, TypeError, AttributeError) as e:
                errors.append(f"{type(e).__name__}: {e}")
        if not errors:
            self._request("set_mapping", mapping)
        return errors

    def load_profile(self, player: str, game: str) -> None:
        def load() -> None:
            calib = profiles.load_calibration(player)
            mapping = profiles.load_mapping(player, game)
            self._request("apply_profile", player, game, calib, mapping, _load_model(player))

        self._worker(load)

    def save_profile(self) -> None:
        def save() -> None:
            if self._calib:
                profiles.save_calibration(self._calib)
            profiles.save_mapping(self.player, self.game, self._mapping)
            if self._model:
                self._model.save(profiles.gesture_model_path(self.player))

        self._worker(save)

    def set_paused(self, on: bool) -> None:
        self._request("set_paused", on)

    def coach_build(self, game: str) -> None:
        def build() -> None:
            calib = self._calib or default_calibration(self.player)
            result = coach.build_mapping(game, calib, self._learned(), self._sip.connected)
            self._event("coach_result", {"mapping": result["mapping"], "rationale": result.get("rationale", []),
                                         "changes": []})

        self._worker(build)

    def coach_review(self) -> None:
        def review() -> None:
            calib = self._calib or default_calibration(self.player)
            stats = {**self._stats.summary(), "notices": self._fatigue.notices()}
            result = coach.review_session(self._mapping, stats, calib, self._learned(), self._sip.connected)
            self._event("coach_result", {"mapping": result["mapping"], "rationale": [],
                                         "changes": result.get("changes", [])})

        self._worker(review)

    def snapshot(self) -> dict:
        """The "state" message of docs/SPEC.md section 8."""
        return self._snapshot

    def preview(self) -> tuple[np.ndarray, np.ndarray | None] | None:
        """Latest bgr frame and landmarks. Under --mock and --replay, a cartoon face drawn from the features
        (landmarks None). None before the first frame."""
        return self._preview

    def pop_events(self) -> list[dict]:
        with self._lock:
            events, self._events = self._events, []
        return events

    # ------------------------------------------------------------------ helpers shared across threads

    def _request(self, kind: str, *args) -> None:
        with self._lock:
            self._requests.append((kind, args))

    def _event(self, name: str, data: dict) -> None:
        with self._lock:
            self._events.append({"type": "event", "name": name, "data": data})

    def _worker(self, fn, *args):
        """Run slow work (disk, coach) off the pipeline thread. Failures become "error" events."""
        def run() -> None:
            try:
                fn(*args)
            except Exception as e:
                log.exception("worker failed")
                self._event("error", {"message": f"{type(e).__name__}: {e}"})

        worker = threading.Thread(target=run, daemon=True)
        worker.start()
        return worker

    def _learned(self) -> list[str]:
        return self._model.names if self._model else []

    # ------------------------------------------------------------------ pipeline thread

    def _loop(self) -> None:
        while not self._stop.is_set():
            try:
                f = self._next_features()
                if f is None:                      # no new frame: keep the pad safe
                    self._pad.apply(ControlState(t_output_ns=time.perf_counter_ns()))
                    continue
                self._step(f)
            except Exception as e:
                key = f"{type(e).__name__}: {e}"
                if key not in self._seen_errors:
                    self._seen_errors.add(key)
                    log.exception("pipeline error (logged once): %s", key)
                try:
                    self._pad.apply(ControlState(t_output_ns=time.perf_counter_ns()))
                except Exception:
                    pass

    def _next_features(self) -> FrameFeatures | None:
        if self._source is not None:
            f = self._source.next()
            if f is None:                          # replay ended
                self._finished.set()
                self._stop.set()
            elif self._draw_preview or self._dev_enabled:
                try:
                    self._video_frame = render_preview(f)
                    self._preview = (self._video_frame, None)
                except Exception:                  # e.g. no cv2: the dashboard shows its placeholder instead
                    self._draw_preview = False
                    log.exception("mock preview disabled")
            return f
        got = self._camera.wait_latest(self._last_seq, timeout=0.5)
        if got is None:
            return None
        bgr, t_capture_ns, seq = got
        self._last_seq = seq
        f = self._tracker.process(bgr, t_capture_ns, seq)
        self._video_frame = bgr
        self._preview = (bgr, f.landmarks)
        return f

    def _step(self, f: FrameFeatures) -> None:
        t_s = f.t_capture_ns / 1e9
        if self._recorder:
            self._recorder.write(f)                # memory only; the file is written on stop
        self._handle_requests()

        progress: Progress | None = None
        if self._calibrator is not None:
            progress = self._calibrator.feed(f, t_s)
            if progress.done:
                self._calib = self._calibrator.result()
                if self._dev_session:
                    self._dev_session.calibration(self._calib)
                    self._dev_end_after_frame = self._dev_session.kind == 'calibration'
                notes = self._calibrator.notes
                self._calibrator = None
                self._normalizer.set_calibration(self._calib)
                self._fatigue = FatigueTracker()   # levels are on a new scale: old baselines no longer compare
                self._rebuild_gestures()
                self._worker(profiles.save_calibration, self._calib)
                self._event("calibration_done", {"mode": self._calib.mode, "reliable": list(self._calib.reliable),
                                                 "range": {a: list(r) for a, r in self._calib.range.items()},
                                                 "notes": notes})
                # Breath range is measured straight after the face, while the player is still in
                # calibration mode, and only when a sensor is actually attached.
                if self._sip.connected:
                    self._breath_cal = BreathCalibrator(self._sip)
                    progress = self._breath_cal.feed(t_s)
        elif self._breath_cal is not None:
            progress = self._breath_cal.feed(t_s)
            if progress.done:
                max_puff, max_sip = self._breath_cal.result()
                notes = self._breath_cal.notes
                self._breath_cal = None
                self._sip.calibrate(max_puff, max_sip)
                self._worker(profiles.save_breath, self.player, max_puff, max_sip)
                self._event("breath_calibration_done",
                            {"max_puff_mv": max_puff, "max_sip_mv": max_sip, "notes": notes})
                progress = None

        s = self._normalizer.update(f, breath=self._sip.level, idle=self._last_idle)

        if self._take_recorder is not None:
            progress = self._take_recorder.feed(s, t_s)
            if progress.done:
                self._finish_recording()
                progress = None

        act = hold_back_crosstalk(self._gestures.update(s), self._competitors)
        scales = self._fatigue.update(act, t_s)
        state = self._mapper.update(s, act, self._sip.poll(), scales)
        self._last_idle = self._mapper.idle

        now = time.perf_counter_ns()
        if f.face:
            self._last_face_ns = now
        face_lost = now - self._last_face_ns > config.FACE_LOST_MS * 1_000_000
        # The breath calibrator tells the player to sip and puff as hard as they can: without it
        # in this guard, the calibration sip slams the brake and the calibration puff latches the
        # throttle while they are doing it.
        neutral = (face_lost or self._calibrator is not None or self._breath_cal is not None
                   or self._take_recorder is not None or state.paused)
        out = ControlState(t_output_ns=state.t_output_ns, paused=state.paused) if neutral else state
        self._pad.apply(out)
        t_output_ns = time.perf_counter_ns()

        self._stats.update(act, self._thresholds, self._tracked, out.fired, t_s, active=not neutral)
        self._hold_fired(out.fired, t_output_ns)
        self._frames += 1
        self._capture_times.append(f.t_capture_ns)
        self._vision_ms.append((f.t_infer_ns - f.t_capture_ns) / 1e6)
        self._control_ms.append((t_output_ns - f.t_infer_ns) / 1e6)
        self._total_ms.append((t_output_ns - f.t_capture_ns) / 1e6)
        if self._dev_session:
            video = self._video_frame
            if video is None:
                video = render_preview(f)
            scores = self._model.predict(s.delta) if self._model else {'none': 1.0}
            if not self._dev_session.submit(video, f, s, act, scores, out, progress):
                self._event('error', {'message': self._dev_session.error or 'Dev recording stopped'})
                self._dev_end_after_frame = True
            if self._dev_end_after_frame:
                self._dev_session.finish('completed')
                self._dev_session = None
                self._dev_end_after_frame = False
        self._snapshot = self._build_snapshot(f, s, act, out, progress)

    def _handle_requests(self) -> None:
        with self._lock:
            requests, self._requests = self._requests, []
        for kind, args in requests:
            getattr(self, "_do_" + kind)(*args)

    def set_dev_mode(self, on: bool) -> None:
        self._request('dev_mode', on)

    def set_dev_recording(self, on: bool) -> None:
        self._request('dev_recording', on)

    def _do_dev_mode(self, on: bool) -> None:
        if not on and self._dev_session:
            self._dev_session.finish('dev_mode_disabled')
            self._dev_session = None
        self._dev_enabled = on
        if on and self._calibrator:
            self._do_calibrate(self._calibrator.mode)
        elif on and self._take_recorder:
            self._start_dev_capture('gesture' if self._take_recorder.name else 'negative', self._take_recorder.name)

    def _do_dev_recording(self, on: bool) -> None:
        if not self._dev_enabled:
            raise ValueError('Enable dev mode before recording a dataset')
        if on:
            if self._dev_session:
                raise ValueError('A dev recording is already active')
            self._start_dev_capture('manual')
        elif self._dev_session and self._dev_session.kind == 'manual':
            self._dev_session.finish('manual_stop')
            self._dev_session = None

    def _start_dev_capture(self, kind: str, label: str | None = None) -> None:
        if not self._dev_enabled:
            return
        if self._dev_session and self._dev_session.kind == 'manual':
            return
        if self._dev_session:
            self._dev_session.finish('replaced')
        self._dev_end_after_frame = False
        self._dev_session = DevRecording(getattr(self.args, 'dev_dir', 'artifacts/dev-datasets'), kind,
                                         self.player, self.game, self._calib or default_calibration(self.player),
                                         self._model.copy() if self._model else GestureModel(), self._mapping,
                                         source='mock' if self.args.mock else 'replay' if self.args.replay else 'camera',
                                         label=label)
        self._dev_sessions.append(self._dev_session)

    def _do_calibrate(self, mode: str) -> None:
        self._take_recorder = None
        if mode == "breath":
            # No dev capture: there is nothing facial to record, and labelling it 'calibration'
            # would put breath takes in the face dataset.
            self._calibrator = None
            self._breath_cal = BreathCalibrator(self._sip)
            return
        self._start_dev_capture('calibration')
        self._breath_cal = None
        self._calibrator = Calibrator(self.player, mode)

    def _do_record(self, name: str | None) -> None:
        self._start_dev_capture('gesture' if name else 'negative', name)
        self._calibrator = None
        self._breath_cal = None
        self._take_recorder = TakeRecorder(name)

    def _do_delete_gesture(self, name: str) -> None:
        if self._model and name in self._model.names:
            model = self._model.copy()
            model.remove(name)
            self._use_model(model, then=None)

    def _do_set_mapping(self, mapping: dict) -> None:
        self._mapping = mapping
        self._mapper.set_mapping(mapping)
        self._rebuild_gestures()

    def _do_apply_profile(self, player: str, game: str, calib, mapping: dict, model) -> None:
        if self._dev_session:
            self._dev_session.finish('profile_changed')
            self._dev_session = None
        self.player, self.game = player, game
        self._breath_cal = None
        self._apply_breath_range(player)
        self._calib, self._mapping, self._model = calib, mapping, model
        self._normalizer = Normalizer(calib)
        self._fatigue = FatigueTracker()
        self._mapper.set_mapping(mapping)
        self._rebuild_gestures()
        self._stats = SessionStats()
        self._event("profile_loaded", {"player": player, "game": game})

    def _apply_breath_range(self, player: str) -> None:
        """This player's measured breath range, or the config defaults. Never inherited: a player
        with no breath.json must not keep the previous player's scale."""
        saved = profiles.load_breath(player)
        self._sip.calibrate(*(saved or (config.BREATH_MAX_PUFF_MV, config.BREATH_MAX_SIP_MV)))

    def _do_set_calibration(self, calib) -> None:
        self._calib = calib
        self._normalizer.set_calibration(calib)
        self._fatigue = FatigueTracker()
        self._rebuild_gestures()

    def _do_set_paused(self, on: bool) -> None:
        self._mapper.set_paused(on)

    def _finish_recording(self) -> None:
        recorder, self._take_recorder = self._take_recorder, None
        if self._dev_session and self._dev_session.kind in ('gesture', 'negative'):
            self._dev_end_after_frame = True
        model = self._model.copy() if self._model else GestureModel()
        for frames in recorder.result():
            if recorder.name is None:
                model.add_negative(frames)
            else:
                model.add_take(recorder.name, frames)
        for frames in recorder.rest:               # relaxed face between takes teaches "none"
            model.add_negative(frames)
        name = recorder.name or "none"

        def report(accuracy: dict[str, float]) -> None:
            score = accuracy.get(name)
            data = {"name": name, "accuracy": score}
            if recorder.name is not None and score is not None and score < config.MIN_TAKE_OUT_ACCURACY:
                data["message"] = (f"{name.replace('_', ' ')} was recognized in {round(score * 100)}% of "
                                   "held-out takes. Record it again to add takes, or make the movement more distinct.")
            self._event("gesture_trained", data)

        self._use_model(model, then=report)

    def _use_model(self, model: GestureModel, then) -> None:
        """Switch to `model` now (it predicts with its previous classifier), fit it and save it on a worker.

        Fitting with leave-one-take-out takes up to about a second, too long for the pipeline thread.
        """
        self._model = model
        self._rebuild_gestures()
        path = profiles.gesture_model_path(self.player)

        dev_session = self._dev_session if self._dev_enabled else None
        dev_version = dev_session.model_update_started() if dev_session else None

        def fit_and_save() -> None:
            error = None
            try:
                accuracy = model.fit()
                if self._model is model:           # a newer recording or profile replaced it: keep that one
                    model.save(path)
                if dev_session:
                    dev_session.save_model(model, dev_version)
                if then:
                    then(accuracy)
            except Exception as e:
                error = e
                raise
            finally:
                if dev_session:
                    dev_session.model_update_finished(error)

        worker = self._worker(fit_and_save)
        if dev_session:
            self._dev_fit_threads.append(worker)

    def _rebuild_gestures(self) -> None:
        defs = self._mapping.get("gestures", {})
        self._gestures = GestureEngine(self._calib, defs, self._model)
        self._thresholds = {name: {"on": g["on"], "off": g["off"]}
                            for name, g in defs.items() if "on" in g and "off" in g}
        self._tracked = {b["gesture"] for b in self._mapping.get("buttons", []) if "gesture" in b}
        used = self._tracked | {t.get("source") for t in self._mapping.get("triggers", []) or []}
        pause = (self._mapping.get("pause") or {}).get("gesture")
        self._competitors = {
            name: (float(g["on"]), frozenset(g.get("sources", []) if g.get("kind") == "blendshape" else ()))
            for name, g in defs.items()
            if name in used and name != pause and g.get("kind") in ("blendshape", "learned")
            and isinstance(g.get("on"), (int, float)) and g["on"] > 0}
        self._catalog_key = None                   # the editor's gesture list is rebuilt on the next snapshot

    def _watch_profiles(self) -> None:
        """Apply hand edits to profiles/<player>/calibration.json and profiles/<player>/<game>.json while running
        (docs/TUNING.md). Polls the files' times once a second, off the pipeline thread. A file that does not parse
        or validate is reported as an error event and not applied. Helm's own saves change nothing."""
        seen: dict[Path, int | None] = {}
        reported: set[str] = set()
        while not self._stop.wait(config.PROFILE_WATCH_S):
            try:
                self._check_profile_files(seen)
            except Exception as e:
                key = f"{type(e).__name__}: {e}"
                if key not in reported:
                    reported.add(key)
                    log.exception("profile watch failed")

    def _check_profile_files(self, seen: dict) -> None:
        folder = Path(profiles.gesture_model_path(self.player)).parent
        for kind, path in (("calibration", folder / "calibration.json"), ("mapping", folder / f"{self.game}.json")):
            try:
                mtime = path.stat().st_mtime_ns
            except OSError:
                mtime = None
            first, changed = path not in seen, seen.get(path) != mtime
            seen[path] = mtime
            if first or not changed or mtime is None:  # first look (or a new player or game) only takes a baseline
                continue
            try:
                data = json.loads(path.read_text())
            except (OSError, ValueError) as e:
                self._event("error", {"message": f"{path.name} was not applied, it does not read as JSON: {e}"})
                continue
            if kind == "calibration":
                calib = profiles.load_calibration(self.player)
                if calib is None:
                    if self.player not in profiles.SHARED_PLAYERS:
                        self._event("error", {"message": f"{path.name} was not applied: a field is missing or has "
                                                         "the wrong shape (see docs/TUNING.md)"})
                    continue
                if calib == self._calib:
                    continue
                self._request("set_calibration", calib)
            else:
                if data == self._mapping:
                    continue
                errors = self.set_mapping(data)
                if errors:
                    self._event("error", {"message": f"{path.name} was not applied: " + "; ".join(errors[:3])})
                    continue
            log.info("applied hand edits to %s", path)
            self._event("profile_reloaded", {"file": f"profiles/{self.player}/{path.name}", "what": kind})

    def _gesture_catalog(self) -> dict:
        """What the mapping editor can use. Cached: rebuilt only when calibration, moves, game or breath change."""
        key = (id(self._calib), tuple(self._learned()), self._sip.connected, self.game)
        if key != self._catalog_key:
            calib = self._calib or default_calibration(self.player)
            self._catalog = coach.gesture_catalog(calib, self._learned(), self._sip.connected, self.game)
            self._catalog_key = key
        return self._catalog

    def _hold_fired(self, fired: tuple[str, ...], now_ns: int) -> list[str]:
        """Keep each fire for FIRED_HOLD_MS: a fire lasts one tick, but the dashboard samples states at 30 Hz."""
        until = now_ns + config.FIRED_HOLD_MS * 1_000_000
        held = {name: t for name, t in self._fired_until.items() if t > now_ns}
        for name in fired:
            held[name] = until
        self._fired_until = held
        return list(held)

    def _build_snapshot(self, f: FrameFeatures | None, s: Signals | None, act: dict[str, float],
                        out: ControlState, progress: Progress | None) -> dict:
        times = self._capture_times
        span_s = (times[-1] - times[0]) / 1e9 if len(times) > 1 else 0.0
        fps = (len(times) - 1) / span_s if span_s > 0 else 0.0

        def median(values: deque) -> float:
            return round(statistics.median(values), 2) if values else 0.0

        return {
            "type": "state",
            "fps": round(fps, 1),
            "latency_ms": {"vision": median(self._vision_ms), "control": median(self._control_ms),
                           "total": median(self._total_ms)},
            "face": bool(f.face) if f else False,
            "paused": out.paused,
            "breath_connected": self._sip.connected,
            "profile": {"player": self.player, "game": self.game,
                        "calibrated": self._calib.mode if self._calib else None},
            "raw": {a: float(getattr(f, a)) if f else 0.0 for a in AXES},
            "axes": {a: float(s.axes[a]) if s else 0.0 for a in AXES},
            "breath": float(s.breath) if s else 0.0,
            "activations": {name: float(level) for name, level in act.items()},
            "thresholds": self._thresholds,
            "control": {"lx": out.lx, "ly": out.ly, "rx": out.rx, "ry": out.ry, "lt": out.lt, "rt": out.rt,
                        "buttons": sorted(out.buttons)},
            "fired": list(self._fired_until),      # held for FIRED_HOLD_MS, see _hold_fired
            "progress": dataclasses.asdict(progress) if progress else None,
            "gestures": {"learned": self._learned(), "reliable": list(self._calib.reliable) if self._calib else []},
            "notices": self._fatigue.notices(),
            "mapping": self._mapping,
            "expressions": {n: float(f.blend[_BLEND_INDEX[n]]) if f and f.face else 0.0 for n in config.WATCH_EXPRESSIONS},
            "catalog": self._gesture_catalog(),
            "dev": {"enabled": self._dev_enabled, "recording": self._dev_session is not None,
                    "session": self._dev_sessions[-1].status() if self._dev_sessions else None},
        }


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    p = argparse.ArgumentParser(prog="python -m helm", description="Helm: hands-free game controller")
    source = p.add_mutually_exclusive_group()
    source.add_argument("--mock", action="store_true", help="synthetic face data instead of the camera")
    source.add_argument("--replay", metavar="PATH", help="replay a recorded .npz instead of the camera")
    p.add_argument('--dev', action='store_true', help='Save calibration/enrollment video and enable debug datasets')
    p.add_argument('--dev-dir', default='artifacts/dev-datasets', help='Local development dataset directory')
    p.add_argument("--record", metavar="PATH", help="save FrameFeatures to a .npz while running")
    p.add_argument("--output", choices=("auto", "vgamepad", "keyboard", "null"), default="auto")
    p.add_argument("--player", default="guest", metavar="NAME")
    p.add_argument("--game", default="SuperTuxKart", metavar="NAME")
    p.add_argument("--camera", type=int, default=0, metavar="N")
    p.add_argument("--port", type=int, default=config.SERVER_PORT)
    p.add_argument("--no-server", action="store_true", help="run the pipeline without the dashboard server")
    p.add_argument("--seconds", type=float, default=None, metavar="N", help="stop after N seconds (with --no-server)")
    p.add_argument("--serial", default="auto", metavar="PORT|auto|off")
    p.add_argument("--no-build", action="store_true", help="do not rebuild the dashboard when its source changed")
    return p.parse_args(argv)


UI_DIR = Path(__file__).resolve().parent.parent / "ui"


def ensure_dashboard(ui: Path = UI_DIR) -> bool:
    """Rebuild ui/dist when the dashboard's source is newer than the build (for example after a git pull), so
    http://localhost:8000 never serves an old page. Runs `npm install` first when the dependencies changed.
    Returns True when the build is current. Without npm, or if the build fails, logs how to fix it and goes on."""
    dist = ui / "dist" / "index.html"
    sources = [p for p in (ui / "src").rglob("*") if p.is_file()]
    sources += [p for p in (ui / "index.html", ui / "package.json", ui / "package-lock.json", ui / "vite.config.ts")
                if p.exists()]
    if not sources:
        return dist.exists()
    if dist.exists() and dist.stat().st_mtime >= max(p.stat().st_mtime for p in sources):
        return True
    npm = shutil.which("npm")
    if not npm:
        log.warning("the dashboard is out of date and npm was not found: run `cd ui && npm install && npm run build`")
        return False
    flags = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0
    installed = ui / "node_modules" / ".package-lock.json"
    lock = ui / "package-lock.json"
    steps = []
    if not installed.exists() or (lock.exists() and lock.stat().st_mtime > installed.stat().st_mtime):
        steps.append([npm, "install", "--no-audit", "--no-fund"])
    steps.append([npm, "run", "build"])
    log.info("the dashboard changed since it was last built: building it now (a few seconds)")
    for cmd in steps:
        try:
            proc = subprocess.run(cmd, cwd=ui, capture_output=True, text=True, timeout=300, creationflags=flags)
        except (OSError, subprocess.TimeoutExpired) as e:
            log.warning("dashboard build failed (%s): run `cd ui && npm install && npm run build`", e)
            return False
        if proc.returncode != 0:
            tail = (proc.stdout + proc.stderr).strip().splitlines()[-8:]
            log.warning("dashboard build failed: `%s` exited %s:\n%s", " ".join(cmd[1:]), proc.returncode, "\n".join(tail))
            return False
    log.info("dashboard built")
    return True


def main() -> None:
    args = parse_args()
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(name)s %(levelname)s %(message)s")
    if not args.no_server and not args.no_build:
        ensure_dashboard()
    runtime = Runtime(args)
    runtime.start()
    try:
        if args.no_server:
            deadline = None if args.seconds is None else time.monotonic() + args.seconds
            while not runtime.finished and (deadline is None or time.monotonic() < deadline):
                time.sleep(0.05)
        else:
            from helm import server            # imported here so --no-server runs without FastAPI

            server.run(runtime, port=args.port)
    except KeyboardInterrupt:
        pass
    finally:
        runtime.stop()
